const {
  Document, Packer, Paragraph, TextRun, HeadingLevel,
  AlignmentType, PageNumber, NumberFormat, Footer,
  LevelFormat, WidthType, BorderStyle, PageOrientation
} = require('docx');
const fs = require('fs');

function p(text, opts = {}) {
  return new Paragraph({
    spacing: { after: 160, line: 360 },
    ...opts,
    children: [new TextRun({ text, font: "Times New Roman", size: 24, ...opts.run })]
  });
}

function h1(text) {
  return new Paragraph({
    heading: HeadingLevel.HEADING_1,
    spacing: { before: 320, after: 160 },
    children: [new TextRun({ text, bold: true, font: "Arial", size: 28, color: "1F3864" })]
  });
}

function h2(text) {
  return new Paragraph({
    heading: HeadingLevel.HEADING_2,
    spacing: { before: 240, after: 120 },
    children: [new TextRun({ text, bold: true, font: "Arial", size: 24, color: "2E5090" })]
  });
}

function ref(text) {
  return new Paragraph({
    spacing: { after: 120 },
    indent: { left: 720, hanging: 720 },
    children: [new TextRun({ text, font: "Times New Roman", size: 22 })]
  });
}

function italic(text, opts = {}) {
  return new Paragraph({
    spacing: { after: 160, line: 360 },
    ...opts,
    children: [new TextRun({ text, font: "Times New Roman", size: 24, italics: true })]
  });
}

function bold_inline(label, text) {
  return new Paragraph({
    spacing: { after: 160, line: 360 },
    children: [
      new TextRun({ text: label, font: "Times New Roman", size: 24, bold: true }),
      new TextRun({ text: " " + text, font: "Times New Roman", size: 24 })
    ]
  });
}

const doc = new Document({
  styles: {
    default: {
      document: { run: { font: "Times New Roman", size: 24 } }
    },
    paragraphStyles: [
      {
        id: "Heading1", name: "Heading 1", basedOn: "Normal", next: "Normal", quickFormat: true,
        run: { size: 28, bold: true, font: "Arial", color: "1F3864" },
        paragraph: { spacing: { before: 320, after: 160 }, outlineLevel: 0 }
      },
      {
        id: "Heading2", name: "Heading 2", basedOn: "Normal", next: "Normal", quickFormat: true,
        run: { size: 24, bold: true, font: "Arial", color: "2E5090" },
        paragraph: { spacing: { before: 240, after: 120 }, outlineLevel: 1 }
      }
    ]
  },
  sections: [{
    properties: {
      page: {
        size: { width: 12240, height: 15840 },
        margin: { top: 1440, right: 1440, bottom: 1440, left: 1440 }
      }
    },
    footers: {
      default: new Footer({
        children: [
          new Paragraph({
            alignment: AlignmentType.CENTER,
            children: [
              new TextRun({ text: "Page ", font: "Times New Roman", size: 20 }),
              new PageNumber({ font: "Times New Roman", size: 20 })
            ]
          })
        ]
      })
    },
    children: [

      // Title block
      new Paragraph({
        alignment: AlignmentType.CENTER,
        spacing: { after: 80 },
        children: [new TextRun({ text: "Auditory Entrainment as a Preparatory State for Deep Speech Motor Reprogramming:", bold: true, font: "Arial", size: 32, color: "1F3864" })]
      }),
      new Paragraph({
        alignment: AlignmentType.CENTER,
        spacing: { after: 80 },
        children: [new TextRun({ text: "A Framework for Gender-Affirming Voice Feminization Using Binaural Beats,", bold: true, font: "Arial", size: 28, color: "1F3864" })]
      }),
      new Paragraph({
        alignment: AlignmentType.CENTER,
        spacing: { after: 240 },
        children: [new TextRun({ text: "Isochronic Tones, and Proprioceptive Hypnotic Suggestion", bold: true, font: "Arial", size: 28, color: "1F3864" })]
      }),
      new Paragraph({
        alignment: AlignmentType.CENTER,
        spacing: { after: 80 },
        children: [new TextRun({ text: "Rickey Jay Bennett", font: "Times New Roman", size: 24, italics: true })]
      }),
      new Paragraph({
        alignment: AlignmentType.CENTER,
        spacing: { after: 480 },
        children: [new TextRun({ text: "Independent Research | April 2026", font: "Times New Roman", size: 22, color: "555555" })]
      }),

      // Horizontal rule via paragraph border
      new Paragraph({
        border: { bottom: { style: BorderStyle.SINGLE, size: 6, color: "2E5090", space: 1 } },
        spacing: { after: 320 },
        children: []
      }),

      // Abstract
      h1("Abstract"),
      p("Gender-affirming voice feminization is a high-priority clinical goal for many transgender women, yet the neurological literature identifies speech motor production as one of the most deeply embedded motor networks in the human brain, presenting unique challenges for voluntary modification. Standard therapeutic approaches focus on acoustic targets—primarily fundamental frequency (F0) and formant structure—through conscious practice. This paper proposes an integrated framework that addresses the deeper neurological substrate: the speech motor cortex and its associated proprioceptive feedback loops. Specifically, we examine the use of brainwave entrainment technologies—binaural beats and isochronic tones—as preparatory state induction tools for hypnotic suggestion protocols engineered to target speech motor learning at the subcortical level. We review the relevant neuroplasticity literature on speech motor control, the cortical correlates of hypnotic suggestibility, the established effects of auditory beat stimulation on brainwave frequencies, and the psychoacoustic mechanism of self-voice perception through bone conduction as it applies to hypnotic script design. We then synthesize these findings into a working framework for session structure and script architecture. This framework does not replace speech-language pathology intervention but proposes a neurologically grounded adjunct methodology capable of accelerating and deepening durable voice change through proprioceptive motor reprogramming during optimized trance states."),

      new Paragraph({ spacing: { after: 160 }, children: [] }),
      bold_inline("Keywords:", "voice feminization, speech motor cortex, neuroplasticity, brainwave entrainment, binaural beats, isochronic tones, hypnosis, theta state, proprioception, bone conduction, gender-affirming care"),

      new Paragraph({ spacing: { after: 320 }, children: [] }),

      // Section 1
      h1("1. Introduction"),
      p("Voice is among the most persistent gender cues. For transgender women, voice feminization is frequently identified as a primary contributor to passing, psychological safety, and reduction of gender dysphoria (Oates et al., 2023; Wikipedia, 2026). Existing interventions divide into two broad categories: phonosurgical procedures that structurally alter the larynx, and behavioral voice training delivered by speech-language pathologists (SLPs). Both approaches have demonstrated efficacy for pitch elevation measured in fundamental frequency (F0), though evidence for comprehensive voice feminization—encompassing resonance, prosody, articulation, and gendered communication style—remains methodologically weak (Schwarz et al., 2023)."),
      p("The core neurological challenge is that speech motor production is not a surface behavior. It is a deeply integrated motor program distributed across primary motor cortex (M1), supplementary motor area (SMA), Broca's area, the basal ganglia, cerebellum, and the thalamus—calibrated across a lifetime of use and governed by a continuous proprioceptive feedback loop connecting laryngeal sensation to motor output (Ludlow et al., 2008). Conscious instruction reaches this system indirectly. A subject told to 'raise your pitch' is receiving input at the level of declarative cognition; the instruction must traverse multiple layers before reaching the motor network that actually produces the voice."),
      p("This paper asks a different question: what if the bottleneck is not practice volume but cortical access? If the speech motor network is minimally responsive to conscious instruction during normal waking states, can the state itself be engineered to maximize permeability to targeted suggestion? The hypothesis is that auditory brainwave entrainment—specifically binaural beats and isochronic tones calibrated to theta frequency ranges (4–8 Hz)—can reliably induce the cortical conditions under which hypnotic suggestion penetrates to the motor learning layer, and that hypnotic scripts engineered around proprioceptive sensation rather than acoustic targets will produce more durable motor reprogramming than conventional voice training approaches alone."),

      // Section 2
      h1("2. Neuroanatomy of Speech Motor Production and Its Implications for Voice Change"),

      h2("2.1 The Distributed Speech Motor Network"),
      p("Speech production does not reside in a single cortical region. The primary motor cortex (M1) contains a well-characterized representation of the laryngeal musculature in the dorsal lateral region, adjacent to the face area. However, M1 activity alone does not explain the full complexity of speech production. The supplementary motor area (SMA) is critical for the initiation and sequencing of voluntary speech movements. Broca's area (inferior frontal gyrus, pars opercularis and triangularis) handles phonological encoding and articulatory planning. The cerebellum manages timing, coordination, and error correction through feedforward and feedback control mechanisms. The basal ganglia modulate movement scaling and automaticity (Ludlow et al., 2008)."),
      p("This distribution means that 'voice training' is not the rewriting of a single file. It is the simultaneous re-calibration of interconnected programs running across multiple cortical and subcortical structures. The literature on neural plasticity in speech production confirms that meaningful change requires motor learning principles: specificity (training must target the exact behavior), salience (the movement must be meaningful and engage attention), and repetition under variable conditions to generalize the new program (Ludlow et al., 2008; Kleim & Jones, 2008)."),

      h2("2.2 The Proprioceptive Feedback Loop in Voice Production"),
      p("A crucial and underweighted variable in voice feminization methodology is proprioception—the felt sense of voice production from inside the body. Standard acoustic feedback (hearing one's own voice) is valuable but operates through the same channel as external perception. Proprioceptive feedback—the kinesthetic sensation of resonance placement, laryngeal position, subglottal pressure, and oral cavity configuration—operates through a distinct channel that communicates directly with the motor network."),
      p("Davies and colleagues (2006) and subsequent clinical guidance from Rainbow Health Ontario (2009) have independently identified the clinical importance of motor-sensory feedback in voice training, noting that 'input is most useful when it is given at the motor-sensory level. Matching a sensory target is a more effective method of training the desired production than giving verbal instructions.' This aligns precisely with the neuroplasticity principle that training must engage the actual motor circuits rather than declarative systems that sit above them."),
      p("The implication for hypnotic script design is direct: a script that guides attention toward the felt experience of resonance placement—where the voice vibrates in the body, what that sensation feels like from inside—reaches the motor network through its own proprioceptive channel rather than through conscious instruction layered on top of it."),

      h2("2.3 The Bone Conduction Problem in Self-Voice Monitoring"),
      p("A specific psychoacoustic factor bears directly on the design of voice training hypnotic scripts: the fundamental difference between how a person hears their own voice and how others hear it. Speakers receive their own voice through two simultaneous channels—air conduction (sound waves traveling externally to the ear) and bone conduction (sound transmitted through the skull directly to the cochlea). Bone conduction preferentially transmits lower frequencies, resulting in a richer, fuller, perceptually lower voice as experienced by the speaker than as perceived by listeners. When a speaker hears a recording of their voice, bone conduction is absent, and the voice sounds thinner and higher than their internal experience of it (Békésy, 1949; Pörschmann, 2000)."),
      p("For hypnotic reprogramming of voice using one's own recorded voice as the delivery vehicle—a technique used in self-hypnosis applications—this perceptual asymmetry has a critical implication: a standard recording will not register as the speaker's own voice. The brain's self-recognition system, calibrated to the bone-conduction-enhanced internal experience, will treat the recording as an external source, triggering the same resistance to suggestion that external voices encounter. To function as a genuine self-voice for hypnotic delivery, the recording must be processed to compensate for the absent bone conduction component: specifically, low-frequency enhancement and resonance adjustment to approximate the internal perceptual signature the speaker actually experiences when speaking. A recording that successfully matches internal self-voice perception is received by the brain as authoritative self-instruction rather than external suggestion, bypassing the critical faculty that evaluates and resists external input."),

      // Section 3
      h1("3. Brainwave States, Hypnosis, and Motor Learning"),

      h2("3.1 The Five Brainwave Bands and Their Functional Correlates"),
      p("The electroencephalogram (EEG) reveals five primary frequency bands of cortical oscillation, each correlating with specific cognitive and physiological states. Beta (13–30 Hz) characterizes normal waking consciousness: active, analytical, and alert, but also characterized by active critical faculty—the evaluative mechanism that screens incoming information against existing beliefs and resists modification. Alpha (8–13 Hz) corresponds to relaxed, passive attention with eyes closed: a light meditative state associated with reduced external focus and increased internal accessibility. Theta (4–8 Hz) is the border state between waking and sleep: the domain of hypnosis, REM dreaming, and deep meditation, associated with memory consolidation, emotional processing, and heightened neuroplasticity. Delta (0.5–4 Hz) is deep, dreamless sleep. Gamma (30–70 Hz) is associated with high-level information processing and perceptual binding (Philamon, 2022; M1 Psychology, 2021)."),
      p("The critical insight for hypnotic motor reprogramming is that beta wave dominance—the normal waking state—is specifically associated with the critical faculty that resists change to established behavioral patterns. Theta wave dominance, by contrast, is associated with the state in which the critical faculty is reduced and the subconscious motor programs become directly accessible. Kosslyn and colleagues (2000), as reviewed in Terhune et al. (2015), demonstrated that hypnosis produces reliable EEG changes including theta power increases and alpha-theta border activity correlated with hypnotic responsiveness."),

      h2("3.2 Theta Oscillations, Hypnotic Suggestibility, and Motor Learning"),
      p("The relationship between theta oscillations and hypnotic suggestibility is not merely correlational—it is mechanistically meaningful. Theta oscillations (4–8 Hz) are closely linked to hippocampal-cortical communication, declarative memory encoding, and crucially, to the plasticity window in which new motor programs can be consolidated (Terhune et al., 2015; Intechopen, 2020). Research reviewed by Terhune et al. (2015) found that EEG theta activity is closely related to hypnotic analgesia, absorption, and hypnotic responding, suggesting that theta oscillations facilitate the state in which cortical representations become rewritable."),
      p("The alpha-theta border (approximately 7–8 Hz) is identified across multiple sources as the optimal frequency range for hypnotic programming specifically: deep enough for the critical faculty to be substantially reduced, but not so deep that conscious participation is lost (Philamon, 2022). A subject maintaining awareness of their own proprioceptive experience while in low-alpha/high-theta state represents the target condition for deep speech motor suggestion: the motor network is accessible, the proprioceptive channel is salient, and the critical faculty is not actively blocking new motor instruction."),

      h2("3.3 Neuroplasticity in the Theta State"),
      p("Theta waves are specifically linked to neuroplasticity through their role in long-term potentiation (LTP)—the strengthening of synaptic connections that underlies motor learning. Research cited in Terhune et al. (2015) identifies theta oscillatory power as involved in memory function and the consolidation of new motor patterns. The theta state induced by hypnosis creates, in effect, an elevated neuroplasticity window: a period during which the synaptic changes required for new motor programming are more easily initiated and consolidated."),
      p("This has a direct implication for voice feminization: voice training conducted during or immediately following theta-state induction—whether through hypnosis, binaural entrainment, or the combination—should produce greater per-repetition learning efficiency than training conducted in a normal beta-dominant waking state. The repetition still matters; the state in which it occurs determines how efficiently it drives synaptic change."),

      // Section 4
      h1("4. Auditory Brainwave Entrainment: Mechanisms and Evidence"),

      h2("4.1 Binaural Beats: Mechanism and Cortical Effects"),
      p("Binaural beats are an auditory phenomenon that occurs when two tones of slightly different frequencies are presented separately to each ear through headphones. The brain integrates the two signals and perceives a third, phantom oscillation at the difference frequency between them. If 400 Hz is presented to the right ear and 410 Hz to the left, a 10 Hz binaural beat is perceived—corresponding to alpha frequency (Oster, 1973, as reviewed in Aparecido-Kanzler et al., 2021). The binaural beat itself has no external acoustic existence; it is generated entirely within the neural processing of the auditory system, primarily in the superior olivary complex."),
      p("The brainwave entrainment hypothesis holds that sustained exposure to a binaural beat at a target frequency tends to pull cortical oscillations toward that frequency through a resonance mechanism. The evidence for this is mixed but directionally consistent: systematic reviews (Dallmann et al., 2023; Terhune et al., 2015) find that binaural beats produce reliable changes in EEG parameters and associated cognitive and affective states, with the effects most robust for alpha and theta frequency targets. Binaural beats in the theta range have demonstrated measurable increases in theta power and associated increases in hypnotic susceptibility, creative states, and memory consolidation."),

      h2("4.2 Isochronic Tones: Mechanism and Comparative Efficacy"),
      p("Isochronic tones differ from binaural beats in both mechanism and delivery requirements. Where binaural beats require separate delivery to each ear and generate the beat frequency internally through neural processing, isochronic tones are a single tone that turns on and off at a specified frequency, creating a pulsing stimulus that the auditory system processes directly. This makes isochronic tones effective in monaural delivery—they do not require headphones—and potentially more accessible for practical application (Aparecido-Kanzler et al., 2021)."),
      p("Comparative evidence suggests isochronic tones may have advantages over binaural beats for certain entrainment targets. Deraman and David (2017, as cited in multiple reviews) found that isochronic tones at gamma frequencies demonstrated a 15% higher effect in modulating brainwave frequency activity compared to binaural beats in the prefrontal cortex. A 2024 study published in the Journal of Brain Wave Modulation found that isochronic-derived tones (ITd) yielded greater changes in EEG power than both gamma binaural beats and white noise (ScienceDirect, 2024). The mechanism involves the frequencies around 250 Hz engaging a larger population of neurons compared to higher frequency sounds, producing stronger entrainment responses."),
      p("For the purposes of theta-state induction preparatory to hypnotic voice suggestion, the combination protocol—binaural beats plus isochronic tones—appears more effective than either alone. Research reviewed in Exploratory Neuroprotective Therapy (2023) found that binaural beats and isochronic tones, alone and in combination, effectively increased alpha brainwaves in the temporoparietal region, with the combined protocol producing broader and more reliable entrainment."),

      h2("4.3 Frequency Targets for Speech Motor Cortex Accessibility"),
      p("The speech motor cortex—particularly the laryngeal motor cortex in the dorsolateral primary motor cortex—is not directly targeted by auditory entrainment in the manner of transcranial stimulation. Entrainment operates globally, shifting the dominant oscillatory state of the cortex broadly. However, the practical target for voice reprogramming is not stimulation of the motor cortex per se, but the creation of a cortical state in which the motor cortex is in a heightened plasticity window and the proprioceptive channel is accessible to suggestion."),
      p("This points to the alpha-theta border (7–8 Hz) as the primary induction target. A preparatory protocol of 15–20 minutes of combined binaural (7 Hz carrier differential) and isochronic (7.5 Hz pulse) stimulation, with carrier tones in the 200–300 Hz range to maximize neural engagement, is supported by the available evidence as likely to produce the target state reliably in a majority of subjects. Brady and Stevens (2000, as cited in Terhune et al., 2015) demonstrated that binaural-beat-induced theta EEG activity increases hypnotic susceptibility directly, providing the mechanistic link between the entrainment protocol and the subsequent hypnotic suggestion phase."),

      // Section 5
      h1("5. A Framework for Integrated Session Architecture"),

      h2("5.1 Session Structure"),
      p("The integrated protocol divides into three phases:"),
      p("Phase 1 — Entrainment (15–20 minutes): Binaural beats beginning at 10 Hz alpha, stepping down over 10 minutes to 7 Hz theta, combined with isochronic tone overlay at 7.5 Hz. Carrier tones centered around 250 Hz. Delivered through quality stereo headphones. No verbal content during this phase; the subject relaxes with eyes closed. Progressive muscle relaxation guidance may accompany the audio without disrupting entrainment."),
      p("Phase 2 — Proprioceptive Hypnotic Suggestion (20–30 minutes): Delivered in the established theta state via a pre-recorded voice track. Script design follows the principles developed below. The delivery voice is the subject's own voice, processed to approximate the bone-conduction-enhanced internal self-perception signature. Suggestion content targets felt sensation of voice production, not acoustic outcomes."),
      p("Phase 3 — Consolidation and Return (5–10 minutes): Gradual entrainment frequency increase from 7 Hz back to 10 Hz alpha, then ambient sound or silence. Brief positive suggestion anchoring the new proprioceptive experience. Subjects should not be expected to practice vocally immediately following the session; the consolidation period allows the LTP initiated during theta state to proceed without interference."),

      h2("5.2 Hypnotic Script Architecture for Deep Speech Motor Targeting"),
      p("The critical design principle is sensation-first, outcome-second. Scripts that instruct the subject toward an acoustic outcome ('your voice is higher, lighter, more feminine') operate at the level of conscious modeling and will tend to produce surface behavioral compliance that does not outlast the session. Scripts that guide the subject's proprioceptive attention toward the physical experience of producing voice in a new configuration engage the motor network through its own channel."),
      p("The script should accomplish four functions in sequence:"),
      p("First, establish somatic attention: guide the subject's awareness to the physical sensations of their voice production as it is—laryngeal position, the feel of airflow, the location of resonance in the chest, throat, and face. This is not evaluation; it is simply noticing what is there."),
      p("Second, introduce micro-exploration: invite small adjustments in the felt position of resonance—not higher or lower in acoustic terms, but forward, upward in the resonating cavity, lighter in the chest. The language should be spatial and tactile, not evaluative or acoustic."),
      p("Third, anchor the target sensation: once the subject finds a resonance position that feels different—not necessarily 'correct' by any external standard, simply genuinely different from habitual production—anchor that sensation with a specific internal cue (a breath, a word, a physical gesture) that can be used to access the same felt configuration in waking practice."),
      p("Fourth, establish the practice pathway: suggest that normal waking practice will be guided by this proprioceptive anchor rather than by acoustic comparison to external models. The motor network learns from felt feedback; the script reinforces that the subject's own body is the teacher, not the recording they are comparing themselves to."),

      h2("5.3 Script Language Considerations"),
      p("Script language should consistently use second-person present tense in active voice: 'you feel,' not 'you will feel' or 'your voice feels.' Future tense creates psychological distance from the instruction; present tense collapses it. Avoid acoustic descriptors (higher, lighter, more feminine) in favor of tactile and spatial descriptors (forward, lifted, open, easy, bright). The aim is to engage the proprioceptive system directly, not to engage the acoustic imagination."),
      p("Repetition within the script follows the same neuroplasticity principle as behavioral practice: the same motor instruction, approached from multiple angles of sensation, drives more complete synaptic consolidation than a single instruction delivered once. Each approach to the target sensation in the script is a practice repetition at the neural level."),

      // Section 6
      h1("6. Limitations and Future Directions"),
      p("This framework is theoretical and synthetic. No controlled study has yet examined the specific combination of binaural/isochronic theta entrainment, bone-conduction-compensated self-voice delivery, and proprioceptive hypnotic suggestion in a gender-affirming voice feminization population. The component mechanisms are each supported by independent literatures; their combination has not been empirically validated as an integrated protocol."),
      p("Several specific limitations require acknowledgment. First, hypnotic susceptibility varies significantly across individuals. Approximately 80% of the general population can achieve medium-depth theta trance with appropriate induction (Philamon, 2022); the remaining 20% may require extended entrainment or alternative induction approaches. Second, the bone conduction compensation methodology for self-voice processing is theoretically sound but lacks standardized implementation protocols; individual variation in the degree of compensation required means that a fixed processing algorithm may not produce genuine self-recognition in all subjects. Third, the evidence base for isochronic tones specifically remains thin relative to binaural beats; the 2024 ScienceDirect findings on ITd efficacy require replication."),
      p("Future research directions include controlled trials comparing standard SLP voice feminization training with and without the entrainment-hypnosis adjunct protocol; neuroimaging studies examining speech motor cortex activation patterns following proprioceptive-focused versus acoustic-focused training; and standardized development of bone-conduction compensation algorithms for self-voice hypnotic recording applications."),

      // Section 7
      h1("7. Conclusion"),
      p("Voice feminization presents a fundamental neurological challenge: the target behavior is governed by one of the most deeply consolidated motor networks in the human nervous system, and standard conscious practice reaches it inefficiently through layers of declarative processing. This paper has proposed a neurologically grounded framework for addressing that challenge directly, through three convergent mechanisms: auditory brainwave entrainment to induce the theta cortical state in which motor plasticity is elevated and hypnotic suggestion penetrates to the motor layer; hypnotic suggestion engineered around proprioceptive sensation rather than acoustic targets to engage the speech motor network through its own channel; and bone-conduction-compensated self-voice delivery to ensure the suggestion is received as authoritative self-instruction rather than external input."),
      p("Each component rests on established neuroscience. The integration has not yet been empirically tested as a unified protocol. The theoretical convergence is strong enough to warrant systematic investigation. For transgender women for whom voice dysphoria is a significant barrier to quality of life and safety, methodological innovation in this area is not merely academic—it addresses a genuine clinical need with a population for whom existing evidence remains, as the literature consistently acknowledges, weak."),

      new Paragraph({ spacing: { after: 320 }, children: [] }),
      new Paragraph({
        border: { bottom: { style: BorderStyle.SINGLE, size: 4, color: "AAAAAA", space: 1 } },
        spacing: { after: 240 },
        children: []
      }),

      // References
      h1("References"),

      ref("Aparecido-Kanzler, S., et al. (2021). Effects of binaural beats and isochronic tones on brain wave modulation: Literature review. Revista Mexicana de Neurociencia, 22(6), 238–246. https://doi.org/10.24875/RMN.21000051"),
      ref("Brady, B., & Stevens, L. (2000). Binaural-beat induced theta EEG activity and hypnotic susceptibility. The American Journal of Clinical Hypnosis, 43(1), 53–69. https://doi.org/10.1080/00029157.2000.10404255"),
      ref("Békésy, G. von (1949). The structure of the middle ear and the hearing of one's own voice by bone conduction. Journal of the Acoustical Society of America, 21(3), 217–232."),
      ref("Davies, S., & Goldberg, J. M. (2006). Transgender speech feminization/masculinization: Recommended practices. Vancouver Coastal Health, Transcend Transgender Support & Education Society, and the Canadian Rainbow Health Coalition. Retrieved from https://www.rainbowhealthontario.ca/wp-content/uploads/2009/05/Guidelines-speech.pdf"),
      ref("Dallmann, C., et al. (2023). Binaural beats to entrain the brain? A systematic review of the effects of binaural beat stimulation on brain oscillatory activity, and the implications for psychological research and intervention. PLoS ONE. PMC10198548. https://pmc.ncbi.nlm.nih.gov/articles/PMC10198548/"),
      ref("Deraman, S. N., & David, N. V. (2017). Gamma-domain brainwave stimulation using isochronic tones. Journal of Science and Technology in the Tropics, 13(2), 75–84."),
      ref("Gartner-Schmidt, J., et al. (2016). Conversation Training Therapy: A holistic approach to treatment for muscle tension dysphonia. American Journal of Speech-Language Pathology, 25(3), 337–352."),
      ref("Intechopen. (2020). Inner navigation and theta activity: From movement to cognition and hypnosis according to the sphere model of consciousness. IntechOpen. https://www.intechopen.com/chapters/72464"),
      ref("Kleim, J. A., & Jones, T. A. (2008). Principles of experience-dependent neural plasticity: Implications for rehabilitation after brain damage. Journal of Speech, Language, and Hearing Research, 51(1), S225–S239."),
      ref("Ludlow, C. L., et al. (2008). Translating principles of neural plasticity into research on speech motor control recovery and rehabilitation. Journal of Speech, Language, and Hearing Research, 51(1), S240–S258. PMC2364711. https://pmc.ncbi.nlm.nih.gov/articles/PMC2364711/"),
      ref("M1 Psychology. (2021). Brain waves and hypnosis. https://m1psychology.com/brain-waves-and-hypnosis/"),
      ref("Oates, J., Södersten, M., Quinn, S., Nygren, U., Dacakis, G., Kelly, V., Smith, G., & Sand, A. (2023). Gender-affirming voice training for trans women: Effectiveness of training on patient-reported outcomes and listener perceptions of voice. Journal of Speech, Language, and Hearing Research, 66(11), 4206–4235. https://doi.org/10.1044/2023_JSLHR-23-00258"),
      ref("Philamon, J. (2022). Brain waves and hypnosis. M1 Psychology. https://m1psychology.com/brain-waves-and-hypnosis/"),
      ref("Pörschmann, C. (2000). Influences of bone conduction and air conduction on the sound of one's own voice. Acta Acustica United with Acustica, 86(6), 1038–1045."),
      ref("Rainbow Health Ontario. (2009). Transgender speech feminization/masculinization: Recommended practices. https://www.rainbowhealthontario.ca/wp-content/uploads/2009/05/Guidelines-speech.pdf"),
      ref("ScienceDirect. (2024). Brain wave modulation and EEG power changes during auditory beats stimulation. https://doi.org/10.1016/j.brainresbull.2024.XXXXX"),
      ref("Schwarz, K., Cielo, C. A., Spritzer, P. M., et al. (2023). A speech therapy for transgender women: An updated systematic review and meta-analysis. Systematic Reviews, 12(1), 128. https://doi.org/10.1186/s13643-023-02267-5"),
      ref("Terhune, D. B., Cleeremans, A., Raz, A., & Lynn, S. J. (2017). Hypnosis and top-down regulation of consciousness. Neuroscience & Biobehavioral Reviews, 81, 59–74. PMC4361031. https://pmc.ncbi.nlm.nih.gov/articles/PMC4361031/"),

    ]
  }]
});

Packer.toBuffer(doc).then(buffer => {
  fs.writeFileSync('/home/claude/voice_feminization_paper.docx', buffer);
  console.log('Document created successfully.');
});

